/**
 * @method
 * @name tx_fn_newListApplContn
 * @description new List Appl Contn 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_newListApplContn = async function () {
    const sbmOptions = {
        id: "tx_fn_newListApplContn",
        method: "post",
        action: "/listInvstg/newListApplContn.do",
        ref: "dma_newListApplContnReq",
        target: "dlt_stkcertIsu=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
