 * @name openIndCodeWin
 * @description open Ind Code Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.openIndCodeWin = function () {
    if (scwin.indCodeWin != null) {
        if (!scwin.indCodeWin.closed) {
            scwin.indCodeWin.close();
        }
    }
    scwin.indCodeWin = (Promise.resolve($c.win.openPopup("/popup_indcode/popup_indcode.xml", { id: "pop_ind", width: "", height: "", scrollbars: false, resizable: false, type: "pageFramePopup" }, { indCodeWin: (typeof scwin.indCodeWin !== 'undefined' ? scwin.indCodeWin : undefined) })).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("pop_ind"); this.closed = true; } });
};

