/**
 * @method
 * @name openStkcertIsuStatDtlWin
 * @description open Stkcert Isu Stat Dtl Win 처리
 * @param {*} stkBzProcsNo stkBzProcsNo
 * @param {*} stkcertIsuSeq stkcertIsuSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openStkcertIsuStatDtlWin = async function (stkBzProcsNo, stkcertIsuSeq) {
    const frm = $c.util.getComponent('NewListStkcertIsuStatDtlForm');
    if ($c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').get('isurCd') === "") {
        $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('isurCd', $c.util.getComponent("dma_openStkcertIsuStatDtlWinReq").get("isurCd2"));
    }
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('stkBzProcsNo', stkBzProcsNo);
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('stkcertIsuSeq', stkcertIsuSeq);
    frm.action = 'newListStkcertIsuStat.do';
    $c.util.getComponent("dma_openStkcertIsuStatDtlWinReq").set("method", 'searchStkcertIsuStatDtl');
    const nr = await scwin.tx_fn_openStkcertIsuStatDtlWin();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil55320/jldfil55320.xml", { "isurCd": $c.util.getComponent("dma_openStkcertIsuStatDtlWinReq").get("isurCd2"), "stkBzProcsNo": stkBzProcsNo, "stkcertIsuSeq": stkcertIsuSeq, "method": 'searchStkcertIsuStatDtl' });
    }
};

