 * @param {String} listTpClssCd listTpClssCd
 * @param {*} tp tp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prtDepo = async function (bzProcsNo, ldMktTpCd, listTpClssCd, tp) {
    const form = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    if ($c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').get('page') === '00' || $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').get('page') === '99' || $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').get('page') === '98') {
        if (form.mode.value === 'new') {
            await $c.win.alert("모든 메뉴는 '기업개요'작성 이후에 작성이 가능합니다.");
        } else {
            await scwin.doPrtDepo(bzProcsNo, ldMktTpCd, listTpClssCd, tp);
        }
    } else {
        await scwin.doPrtDepo(bzProcsNo, ldMktTpCd, listTpClssCd, tp);
    }
};

/**
 * @method
 * @name doPrtDepo
 * @description do Prt Depo 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} listTpClssCd listTpClssCd
 * @param {*} tp tp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doPrtDepo = async function (bzProcsNo, ldMktTpCd, listTpClssCd, tp) {
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    if (await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) {
        frm.action = '/listInvstg/listPrePrtDepo.do';
        $c.util.getComponent("dma_openStkcertIsuStatDtlWinReq").set("method", 'getlistPrePrtDepo');
        $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('page', '40');
        $c.util.getComponent("dma_openStkcertIsuStatDtlWinReq").set("bzProcsNo", "" + bzProcsNo);
        $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('ldMktTpCd', "" + ldMktTpCd);
        if (frm.gongMo !== 'undefined') {
            if ($c.util.getComponent("dma_openStkcertIsuStatDtlWinReq").get("gongMo") === 'Y') {
                $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('listInvstgBzTpCd', '140');
            } else {
                $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('listInvstgBzTpCd', '120');
            }
        }
        $c.util.getComponent("dma_openStkcertIsuStatDtlWinReq").set("view", tp);
        const nr = await scwin.tx_doPrtDepo();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil51090/jldfil51090.xml", { "method": 'getlistPrePrtDepo', "page": '40', "listInvstgBzTpCd": '140', "view": tp });
        }
    }
};
